import { useEffect, useRef, useMemo, useState, type FormEvent } from 'react';
import { Bell, Check, CheckCheck, ChevronRight, Download, FileText, History, LoaderCircle, MessageSquare, Paperclip, Plus, Search, Send, Settings, Sparkles, Upload, X } from 'lucide-react';
